#[cfg(test)]
mod w335_tests {
    use super::*;
    use crate::{contracts::ProcessToolOwner, domain::{ToolSafety,ToolSpec}};
    use serde_json::json;

    #[test]
    fn w335_summary_projects_tool_snapshot_before_wait() {
        let empty:AppConfig=serde_json::from_value(json!({})).unwrap();
        let variants=[
            (ToolSource::builtin("fixture builtin"),ToolSafety::ReadOnly),
            (ToolSource::ProviderHosted{provider:"fixture provider".into()},ToolSafety::WritesFiles),
            (ToolSource::Mcp{server:"тест mcp".into()},ToolSafety::RunsCommands),
            (ToolSource::Process{owner:ProcessToolOwner{component_id:"fixture".into(),module_id:"модуль".into()}},ToolSafety::Network),
            (ToolSource::Dynamic{origin:"тестовый".into()},ToolSafety::Dangerous),
        ];
        for n in [0,5,128] {
            let mut entries=Vec::new();
            for i in 0..n {
                let (source,safety)=&variants[i%variants.len()];
                let meta=if n>5 {json!({"extra":"μ".repeat(768),"nest":[{"v":"z".repeat(1024)}]})} else {Value::Null};
                let schema=if n>5 {json!({"type":"object","properties":{"value":{"description":"文".repeat(1024),"enum":["x".repeat(128),"y".repeat(256)]}}})} else {json!({"type":"object"})};
                let mut desc=String::with_capacity(512);
                desc.push_str(if i%2==0 {"описание\nдальше"} else {""});
                let tool=ToolSpec::new(format!("fixture-{i:03}"),desc,schema,safety.clone())
                    .with_parallel_tool_calls(i%3==0).with_timeout(123).with_metadata(meta);
                entries.push((source.clone(),tool));
            }
            let expected_section=if entries.is_empty() {"  (none)".into()} else {
                entries.iter().map(|(s,t)|format!("  - {} [{} {:?}] {}",t.name,s.label(),t.safety,t.description)).collect::<Vec<_>>().join("\n")
            };
            let expected_dto=serde_json::to_value(registered_tool_summaries(entries.clone())).unwrap();
            let ((display,dto),m,end)=crate::w335_alloc::measure(||{
                let tools=entries.clone();
                crate::w335_alloc::metadata();
                let display=render_config_summary(&empty,None,Path::new("/synthetic/workspace"),
                    PermissionMode::Normal,&tools,crate::core::ModuleEpoch::initial());
                let dto=registered_tool_summaries(tools);
                (display,dto)
            });
            assert_eq!(display.split_once("registered tools:\n").unwrap().1,expected_section);
            assert_eq!(serde_json::to_value(&dto).unwrap(),expected_dto);
            if let Some(dir)=std::env::var_os("W335_WITNESS_DIR") {
                std::fs::write(std::path::PathBuf::from(dir).join(format!("{n}.json")),
                    serde_json::to_vec(&(display,dto)).unwrap()).unwrap();
            }
            eprintln!("W335 {n} {} {} {end}",m.metadata.unwrap(),m.peak);
        }
    }
}

